function home(){currentLeague=null;nav.classList.add("hidden");app.innerHTML=`<div class="page-heading"><div><div class="eyebrow">Your listening rooms</div><h1>Good to see you, Nora</h1><p class="subhead">Pick up where your leagues left off.</p></div><div class="heading-actions"><button class="button button-secondary" data-action="join">＋ Join League</button><button class="button button-primary" data-action="create">＋ Create League</button></div></div><div class="section-title"><h2>Your leagues <span class="meta-line">· ${leagues.length}</span></h2><button class="text-button" data-action="reorder">${reorderMode?"Done":"↕ Reorder"}</button></div><div class="league-grid">${leagues.map(card).join("")}</div>`}
function hasVoted(l){return localStorage.getItem(`encore-vote-submitted-${l.id}`)==="true"}
