function card(l){const ready=l.status!=="between",i=leagues.indexOf(l),voted=hasVoted(l),submitted=hasSubmitted(l);let actions="";if(l.status==="voting"){actions=`<button class="button button-secondary" data-action="playlist">♫ Playlist</button><button class="button ${voted?"button-secondary":"button-primary"}" ${voted?"disabled":"data-action=\"vote-league\""} data-id="${l.id}">${voted?"✓ Voted":"Vote Now"}</button>`}else if(l.status==="submission"){actions=`<button class="button button-secondary" data-action="open-results" data-id="${l.id}">View Last Round Results</button><button class="button ${submitted?"button-secondary":"button-primary"}" ${submitted?"disabled":"data-action=\"submit-song\""} data-id="${l.id}">${submitted?"✓ Submitted":"Submit a Song"}</button>`}else actions=`<button class="button button-secondary" data-action="open-results" data-id="${l.id}">View Results</button>`;return `<article class="league-card"><button type="button" class="league-card-open" data-action="open-league" data-id="${l.id}" aria-label="Open ${l.name}"></button><div class="league-art ${l.art}"><span class="art-label">${l.label}</span></div><div class="league-card-body"><div class="card-title-row"><div><h3>${l.name}</h3><div class="meta-line">${l.season} · ${l.players} players</div></div><span class="pill ${ready?"":"neutral"}">${ready?(l.status==="voting"?"Voting open":"Submissions open"):"Between rounds"}</span></div><p class="round-name">${l.round}</p><div class="card-foot"><span class="deadline ${ready?"ready":""}"><span class="dot" style="${ready?"":"background:#aeb5ae"}"></span>${l.deadline}</span>${reorderMode?`<span><button class="button button-secondary reorder-arrow" aria-label="Move up" data-action="reorder-up" data-index="${i}" ${i===0?"disabled":""}>↑</button> <button class="button button-secondary reorder-arrow" aria-label="Move down" data-action="reorder-down" data-index="${i}" ${i===leagues.length-1?"disabled":""}>↓</button></span>`:`<div class="card-actions">${actions}</div>`}</div></div></article>`}
