function renderLeagueHome(l){const voting=l.status==="voting",submission=l.status==="submission";app.innerHTML=`<button class="back-link" data-action="home">← All leagues</button><section class="league-hero ${l.art}"><div class="hero-tools"><button class="hero-tool" data-action="info" aria-label="League information">ⓘ</button><button class="hero-tool" data-action="settings" aria-label="League settings">⚙</button></div><div class="hero-content"><div class="eyebrow">${l.season} · ${l.players} players</div><h1>${l.name}</h1><div class="hero-meta">A shared soundtrack, one round at a time.</div></div></section><div class="search-wrap"><label class="search-box"><span>⌕</span><input id="league-search" type="search" placeholder="Search previously submitted songs & artists…" value="${escapeHtml(query)}" autocomplete="off" /></label><div id="search-results" class="search-results"></div></div><div class="eyebrow">Current round</div><section class="current-round"><div class="round-main"><div class="round-kicker">Round ${l.roundNo} ${voting?"· Voting open":submission?"· Submissions open":"· Results ready"}</div><h2>${l.theme}</h2><p class="round-description">${l.description}</p><div class="round-actions">${voting?`<button class="button button-secondary" data-action="playlist">♫ &nbsp;Listen to Playlist</button><button class="button button-primary" data-action="vote">Vote Now</button>`:submission?`<button class="button button-primary" data-action="submit-song">Submit a Song</button>`:`<button class="button button-primary" data-action="results">View Results</button>`}</div></div><aside class="round-aside"><span class="countdown-label">${voting?"Voting deadline":submission?"Submission deadline":"Next round starts"}</span><strong class="countdown">${voting?"1 day":submission?"3 days":"Thursday"}</strong><span class="round-deadline">${l.short}</span><div class="people-summary"><strong>${voting?`${l.voted} of ${l.players} voted`:submission?`${l.submitted} of ${l.players} submitted`:"Everyone is caught up"}</strong><br>${(voting||submission)?`Waiting on ${l.missing||"everyone"}`:"Next theme drops soon"}</div></aside></section><div class="section-title"><h2>Previous round</h2><span class="meta-line">${l.previous.round.split(" · ")[0]}</span></div><section class="past-card"><div class="meta-line">${l.previous.round}</div><div class="podium">${l.previous.winners.map(([n,s],i)=>`<div class="winner"><span class="medal">${["1","2","3"][i]}</span><span><strong>${n}</strong><span class="winner-score"> · ${s}</span></span></div>`).join("")}</div><button class="button button-secondary" data-action="results">View Round Results</button></section><div class="section-title"><h2>Up next</h2><span class="meta-line">${l.future.length} rounds</span></div><div class="future-list">${l.future.map(([n,t,d])=>`<article class="future-item"><span class="round-number">Round ${n}</span><strong>${t}</strong><span>${d} · Scheduled</span></article>`).join("")}</div>`;const input=document.querySelector("#league-search");input.addEventListener("input",e=>{query=e.target.value;const box=document.querySelector("#search-results");box.classList.toggle("open",!!query);box.innerHTML=query?`<div class="search-hit"><strong>“${escapeHtml(query)}”</strong><br><span class="meta-line">Search past songs and artists across ${l.season.toLowerCase()}.</span></div><div class="search-hit">Example result · Dreams — Fleetwood Mac <span class="meta-line">Round 2</span></div>`:""})}
function roundVoteSettings(l){const saved=readSaved(`encore-round-vote-settings-${l.id}`,{});return{enabled:saved.enabled??true,thresholdEnabled:saved.thresholdEnabled??true,minVoters:Number(saved.minVoters)||Math.ceil(l.players*.5)}}
function roundThemeSettings(l){const saved=readSaved(`encore-round-theme-settings-${l.id}`,{});return{mode:saved.mode||"vote",promptSource:saved.promptSource||"pool"}}
function pickerOrder(l){return readSaved(`encore-round-picker-order-${l.id}`,null)||["You",...players.slice(0,l.players).map(p=>p.name).filter(name=>name!=="You")]}
function pickerForRound(l,roundNumber){const order=pickerOrder(l),offset=Math.max(0,roundNumber-(l.roundNo+1));return order.length?order[offset%order.length]:"League admin"}
function roundThemeHistory(l){const prior=Object.values(readSaved(`encore-round-pick-history-${l.id}`,{})).map(p=>p.title),previous=l.previous?.round?.split(" · ").slice(1).join(" · ")||"";return [l.theme,previous,...Object.entries(resultRoundNames).filter(([number])=>Number(number)<l.roundNo).map(([,title])=>title),...prior].filter(Boolean).map(title=>title.trim().toLowerCase())}
function availablePromptPool(l){const used=new Set(roundThemeHistory(l));return appRoundPrompts.filter(prompt=>!used.has(prompt.title.toLowerCase()))}
