function readSaved(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function getChatMessages(l){const saved=readSaved(`encore-chat-${l.id}`,null);if(saved)return saved;return[{id:"welcome",author:"Maya Chen",role:"Player",text:"That playlist is already setting the mood for the week.",createdAt:"Today · 9:12 AM",announcement:false,pinned:false},{id:"admin-note",author:l.manager||"You",role:"League admin",text:"Quick reminder: voting closes tomorrow at 8 PM. Add your guesses before then!",createdAt:"Today · 8:30 AM",announcement:true,pinned:true},{id:"reply",author:"Jordan Lee",role:"Player",text:"Got it. I’m excited to see the results for this one.",createdAt:"Today · 8:46 AM",announcement:false,pinned:false}]}
function renderChat(l,heading){
 const isAdmin=l.manager==="You",messages=getChatMessages(l),pinned=messages.filter(m=>m.pinned),reactionKinds=[["👍","Thumbs up"],["😂","Ha ha"],["❓","Question"],["👎","Thumbs down"]];
 const chatItems=messages.map(m=>{const reactions=m.reactions||{},existing=reactionKinds.filter(([emoji])=>(reactions[emoji]||[]).length),reactionButtons=existing.map(([emoji,label])=>{const users=reactions[emoji]||[];return `<button type="button" class="chat-reaction ${users.includes("You")?"active":""}" data-action="chat-react" data-message-id="${escapeHtml(m.id)}" data-emoji="${emoji}" aria-label="${label}, ${users.length} reactions" aria-pressed="${users.includes("You")}">${emoji}<span>${users.length}</span></button>`}).join(""),reactionChoices=reactionKinds.map(([emoji,label])=>`<button type="button" class="chat-reaction-choice" data-action="chat-react" data-message-id="${escapeHtml(m.id)}" data-emoji="${emoji}" aria-label="React with ${label}">${emoji}</button>`).join("");return `<article class="chat-message ${m.announcement?"is-announcement":""}"><header><div><strong>${escapeHtml(m.author)}</strong>${m.announcement?'<span class="chat-role">Admin announcement</span>':`<span class="chat-role">${escapeHtml(m.role||"Player")}</span>`}</div><time>${escapeHtml(m.createdAt)}</time></header><p>${escapeHtml(m.text)}</p><div class="chat-reaction-row ${existing.length?"has-reactions":""}">${existing.length?`<div class="chat-reactions" aria-label="Reactions">${reactionButtons}</div>`:""}<div class="chat-reaction-add"><button type="button" class="chat-reaction-plus" data-action="toggle-reaction-picker" aria-label="Add a reaction" aria-expanded="false">＋</button><div class="chat-reaction-picker" hidden>${reactionChoices}</div></div></div>${isAdmin&&!m.pinned?`<button type="button" class="chat-pin-button" data-action="chat-pin" data-message-id="${escapeHtml(m.id)}">📌 Pin message</button>`:""}</article>`}).join("");
 const pinnedItems=pinned.map(m=>`<article class="pinned-announcement"><span class="pinned-label">📌 ${m.announcement?"Admin announcement":"Pinned message"}</span><strong>${escapeHtml(m.author)}</strong><p>${escapeHtml(m.text)}</p><time>${escapeHtml(m.createdAt)}</time>${isAdmin?`<button type="button" class="chat-pin-button" data-action="chat-unpin" data-message-id="${escapeHtml(m.id)}">Unpin message</button>`:""}</article>`).join("");
 app.innerHTML=`${heading}<div class="chat-layout"><section class="chat-panel"><div class="chat-feed" aria-live="polite">${chatItems||'<p class="chat-empty">No messages yet. Start the conversation.</p>'}</div><div class="chat-composer"><label for="chat-message">Message the league</label><textarea id="chat-message" maxlength="2000" placeholder="Write a message…"></textarea>${isAdmin?`<div class="chat-composer-options"><label><input type="checkbox" id="chat-announcement"> Post as admin announcement</label></div>`:`<p class="chat-member-note">Only league admins can post announcements.</p>`}<div class="chat-compose-footer"><small>Posting as <strong>${escapeHtml(l.manager||"You")}</strong>${isAdmin?" · League admin":""}</small><button class="button button-primary" data-action="chat-send">Send</button></div></div></section><aside class="chat-announcements"><div class="eyebrow">Pinned messages</div><h2>Pinned announcements</h2><p class="chat-aside-note">Important pinned messages and announcements from your league.</p>${pinnedItems||'<p class="chat-empty-pinned">No pinned messages yet.</p>'}</aside></div>`
}
function saveProgress(){const key=`encore-progress-${currentLeague.id}`;localStorage.setItem(key,JSON.stringify({votes,comments}));}
function getVoteTotals(){const values=Object.values(votes).map(v=>Number(v)||0);return{ups:values.reduce((n,v)=>n+Math.max(0,v),0),downs:values.reduce((n,v)=>n+Math.max(0,-v),0)}}
function renderVoting(l){
 const saved=readSaved(`encore-progress-${l.id}`,{}),guesses=readSaved(`encore-guesses-${l.id}`,{}),leaguePlayers=players.slice(0,l.players),guessLocked=readSaved(`encore-guesses-locked-${l.id}`,false);votes=saved.votes||{};comments=saved.comments||{};const {ups,downs}=getVoteTotals();
 const cards=roundSongs.map((s,i)=>{const value=Number(votes[i]||0),nextUpValue=Math.max(0,value+1)-Math.max(0,value),wouldExceedUps=ups+nextUpValue>2;return `<article class="vote-card ${s.own?"own-song":""}" data-song-card="${i}"><div class="album-art album-${i%6}"><span class="album-initials">${s.title.split(" ").slice(0,2).map(x=>x[0]).join("")}</span><button class="preview-button" data-action="preview-song" data-index="${i}" aria-label="Play preview of ${s.title}" disabled title="Loading preview">▶</button></div><div class="vote-song-main"><div class="vote-song-heading"><div><h3>${s.title}</h3><p>${s.artist}</p><span class="album-meta">${s.album}</span><span class="apple-link-slot" data-apple-link="${i}"></span></div>${s.own?`<span class="pill neutral">Your submission</span>`:`<label class="guess-control"><span>Guess who</span><select aria-label="Guess who submitted ${s.title}" data-guess="${i}" ${guessLocked?"disabled":""}><option value="">Guess submitter</option>${leaguePlayers.filter(p=>p.name!=="You").map(p=>`<option ${guesses[i]===p.name?"selected":""}>${p.name}</option>`).join("")}</select></label>`}</div><div class="vote-card-bottom"><label class="comment-label">Comment<textarea data-comment="${i}" placeholder="Add a comment…">${escapeHtml(comments[i]||"")}</textarea></label><div class="vote-control"><button data-action="vote-step" data-index="${i}" data-step="-1" aria-label="Remove a vote" ${s.own||value<=-1?"disabled":""}>−</button><strong class="vote-count ${value>0?"positive":value<0?"negative":""}">${value>0?`+${value}`:value}</strong><button data-action="vote-step" data-index="${i}" data-step="1" aria-label="Add a vote" ${s.own||value>=2||wouldExceedUps?"disabled":""}>＋</button></div></div></div></article>`}).join("");
 const valid=ups===2&&downs===1;
 app.innerHTML=`<button class="back-link" data-action="back-league">← ${l.name}</button><div class="voting-heading"><div><div class="eyebrow">Round ${l.roundNo} · Voting open</div><h1>${l.theme}</h1><p class="subhead">${l.description}</p></div><button class="button button-secondary" data-action="playlist">♫ &nbsp;Listen to Round Playlist</button></div><div class="song-list">${cards}</div><footer class="vote-footer"><div class="vote-progress"><strong>Votes allocated</strong><span>${ups}/2 upvotes · ${downs}/1 downvote</span><small>✓ Progress saved on this device</small></div><button class="button button-primary" data-action="submit-votes" ${valid?"":"disabled"}>Submit Votes</button></footer>`;
 app.querySelectorAll("[data-comment]").forEach(el=>el.addEventListener("input",e=>{comments[e.target.dataset.comment]=e.target.value;saveProgress()}));
 roundSongs.forEach((song,index)=>loadPreviewMetadata(song,index));
}
async function loadPreviewMetadata(song,index){
 if(song.catalogLoaded){applyCatalogMetadata(song,index);return}
 if(catalogCache.has(song.title)){Object.assign(song,catalogCache.get(song.title));song.catalogLoaded=true;applyCatalogMetadata(song,index);return}
 song.catalogLoaded=true;
 try{const term=encodeURIComponent(`${song.title} ${song.artist}`),response=await fetch(`https://itunes.apple.com/search?term=${term}&entity=song&limit=8&country=US`);if(!response.ok)throw new Error("Catalog lookup failed");const data=await response.json(),norm=s=>String(s||"").toLowerCase().replace(/[^a-z0-9]/g,"");const match=(data.results||[]).find(item=>norm(item.trackName)===norm(song.title)&&norm(item.artistName)===norm(song.artist));if(!match)throw new Error("No exact catalog match");const metadata={previewUrl:match.previewUrl||"",artworkUrl:(match.artworkUrl100||"").replace("100x100","400x400"),storeUrl:match.trackViewUrl||""};catalogCache.set(song.title,metadata);Object.assign(song,metadata);applyCatalogMetadata(song,index)}catch{const card=app.querySelector(`[data-song-card="${index}"]`);if(card){const button=card.querySelector(".preview-button");button.disabled=true;button.title="Preview unavailable";button.setAttribute("aria-label",`Preview unavailable for ${song.title}`);button.textContent="♪"}}
}
function applyCatalogMetadata(song,index){const card=app.querySelector(`[data-song-card="${index}"]`);if(!card)return;if(song.artworkUrl)card.querySelector(".album-art").style.backgroundImage=`url("${song.artworkUrl}")`;const initials=card.querySelector(".album-initials");if(initials)initials.hidden=!!song.artworkUrl;const button=card.querySelector(".preview-button");button.disabled=!song.previewUrl;button.title=song.previewUrl?"Play 30-second preview":"Preview unavailable";button.textContent=activePreview?.index===index&&activePreview.playing?"Ⅱ":"▶";button.setAttribute("aria-label",`${activePreview?.index===index&&activePreview.playing?"Pause":"Play"} preview of ${song.title}`);const slot=card.querySelector("[data-apple-link]");if(song.storeUrl)slot.innerHTML=`<a class="apple-store-link" href="${song.storeUrl}" target="_blank" rel="noreferrer">Listen on Apple Music ↗</a>`}
function togglePreview(index){const song=roundSongs[index];if(!song?.previewUrl){toast("Preview is still loading or unavailable.");return}if(activePreview?.index===index&&activePreview.playing){activePreview.audio.pause();activePreview.playing=false;applyCatalogMetadata(song,index);return}if(activePreview?.audio){activePreview.audio.pause();activePreview.audio.currentTime=0;const old=roundSongs[activePreview.index];activePreview.playing=false;applyCatalogMetadata(old,activePreview.index)}const audio=new Audio(song.previewUrl);activePreview={audio,index,playing:true};audio.addEventListener("ended",()=>{if(activePreview?.audio===audio){activePreview.playing=false;applyCatalogMetadata(song,index)}});audio.play().then(()=>applyCatalogMetadata(song,index)).catch(()=>{activePreview.playing=false;toast("This preview could not be played.");applyCatalogMetadata(song,index)})}
function renderVoteSubmitted(l){app.innerHTML=`<section class="confirmation-card"><div class="confirmation-check">✓</div><div class="eyebrow">Round ${l.roundNo}</div><h1>Votes Submitted!</h1><p>Your votes and comments are saved. You can still review, edit, or lock your guesses while voting is open.</p><div class="confirmation-actions"><button class="button button-primary" data-action="guess-page">Edit guesses</button><button class="button button-secondary" data-action="back-league">Back to League Home</button></div></section>`}
function renderGuessPage(l){const guesses=readSaved(`encore-guesses-${l.id}`,{}),locked=readSaved(`encore-guesses-locked-${l.id}`,false),items=roundSongs.map((song,i)=>`<article class="guess-row"><div class="guess-song-art album-${i%6}" ${song.artworkUrl?`style="background-image:url('${song.artworkUrl}')"`:""}>${song.artworkUrl?"":song.title.split(" ").slice(0,2).map(x=>x[0]).join("")}</div><div class="guess-song-copy"><strong>${song.title}</strong><span>${song.artist} · ${song.album}</span></div>${song.own?`<span class="pill neutral">Your submission</span>`:`<label class="guess-review-control"><span>Submitted by</span><select data-guess="${i}" ${locked?"disabled":""}><option value="">Choose a player</option>${players.slice(0,l.players).filter(p=>p.name!=="You").map(p=>`<option ${guesses[i]===p.name?"selected":""}>${p.name}</option>`).join("")}</select></label>`}</article>`).join("");app.innerHTML=`<button class="back-link" data-action="back-league">← ${l.name}</button><div class="guess-page-heading"><div class="eyebrow">Round ${l.roundNo} · Optional side quest</div><h1>Guess Who Submitted</h1><p class="subhead">Review your picks for each song. Change a guess or choose a player where you left it blank.</p></div><div class="guess-review-list">${items}</div><footer class="guess-footer"><span>${locked?"Guesses are locked in.":"Your guesses save automatically."}</span><div><button class="button button-secondary" data-action="save-guesses">Back to League Home</button><button class="button button-primary" data-action="lock-guesses" ${locked?"disabled":""}>${locked?"Guesses Locked":"Lock Guesses"}</button></div></footer>`}
